	u, _ := url.Parse("http://localhost")

	p, err := http.New(options...)
	if err != nil {
		panic(err)
	}
	p.Client = NewTestClient(func(req *nethttp.Request) *nethttp.Response {
		return &nethttp.Response{
			StatusCode: 202,
			Header:     make(nethttp.Header),
		}
	})
	p.Target = u
	return p
}

